instruction: Debug the following C++ code that is supposed to print the elements of a 2D array but instead crashes without any clear error message. Also, enhance the code by adding functions to perform column and row major traversals of the 2D array.

response: ## Debugging and Enhancing 2D Array Code

### Common Causes of Crashes
Without seeing your specific code, here are the most common reasons why 2D array printing code crashes:

1. **Out-of-bounds access**: Loop indices exceeding array dimensions
2. **Null pointer dereference**: Accessing uninitialized or deleted memory
3. **Memory corruption**: Double deletion or writing beyond allocated memory
4. **Incorrect array sizing**: Mismatch between allocated and accessed sizes

### Example of Buggy Code and Fix

**Buggy Version (likely to crash):**
```cpp
void print2DArray(int** arr, int rows, int cols) {
    for (int i = 0; i <= rows; i++) {  // BUG: should be < not <=
        for (int j = 0; j <= cols; j++) {  // BUG: should be < not <=
            std::cout << arr[i][j] << " ";
        }
        std::cout << std::endl;
    }
}
```

**Corrected and Enhanced Version:**
```cpp
#include <iostream>
#include <vector>

// Row-major traversal (row by row)
template<typename T>
void traverseRowMajor(T** arr, int rows, int cols) {
    std::cout << "Row-major traversal:\n";
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            std::cout << arr[i][j] << " ";
        }
        std::cout << std::endl;
    }
}

// Column-major traversal (column by column)
template<typename T>
void traverseColumnMajor(T** arr, int rows, int cols) {
    std::cout << "Column-major traversal:\n";
    for (int j = 0; j < cols; j++) {
        for (int i = 0; i < rows; i++) {
            std::cout << arr[i][j] << " ";
        }
        std::cout << std::endl;
    }
}

// Safe printing function with bounds checking
template<typename T>
void print2DSafe(T** arr, int rows, int cols) {
    if (!arr) {
        std::cerr << "Error: Null pointer passed!\n";
        return;
    }

    for (int i = 0; i < rows; i++) {
        if (!arr[i]) {
            std::cerr << "Error: Null pointer at row " << i << "!\n";
            continue;
        }
        for (int j = 0; j < cols; j++) {
            std::cout << arr[i][j] << " ";
        }
        std::cout << std::endl;
    }
}

// Modern C++ alternative using vector (recommended)
void print2DVector(const std::vector<std::vector<int>>& vec) {
    for (const auto& row : vec) {
        for (int val : row) {
            std::cout << val << " ";
        }
        std::cout << std::endl;
    }
}

int main() {
    // Example usage with dynamic allocation
    int rows = 3, cols = 4;
    int** arr = new int*[rows];

    // Allocate and initialize
    for (int i = 0; i < rows; i++) {
        arr[i] = new int[cols];
        for (int j = 0; j < cols; j++) {
            arr[i][j] = i * cols + j;
        }
    }

    // Print using different methods
    print2DSafe(arr, rows, cols);
    std::cout << "\n";
    traverseRowMajor(arr, rows, cols);
    std::cout << "\n";
    traverseColumnMajor(arr, rows, cols);

    // Clean up
    for (int i = 0; i < rows; i++) {
        delete[] arr[i];
    }
    delete[] arr;

    return 0;
}
```

### Key Fixes Applied:
1. Changed `<=` to `<` in loop conditions
2. Added null pointer checks
3. Used templates for flexibility
4. Implemented separate traversal functions
5. Added proper memory cleanup
6. Provided modern vector-based alternative

